import { requestRecovery, type RecoveryUser } from './solution';
async function main() {
  const unrelated = {email:null, enabled:true, locked:false} as unknown as RecoveryUser;
  const result = await requestRecovery('a@b.com', [unrelated, {email:'a@b.com', enabled:true, locked:false}]);
  if (result !== 'Recovery instructions queued') throw new Error('Unrelated malformed email must be a nonmatch');
}
main().catch(error => { throw error; });

prompt.text:
Implement a deterministic account-recovery simulator with no timers or external services.

Export:

```ts
export interface RecoveryUser {
  readonly email: string;
  readonly enabled: boolean;
  readonly locked: boolean;
}
export function requestRecovery(
  email: string,
  users: readonly RecoveryUser[],
): Promise<string>;
```

Trim and lowercase the requested email. Reject with `Error("Email is required")` when it becomes empty and with `Error("Invalid email")` unless it matches `/^[^\s@]+@[^\s@]+\.[^\s@]+$/`. User email addresses are compared after the same trim-and-lowercase normalization. If no user matches, reject with `Error("Account not found")`. If multiple users normalize to the requested address, reject with `Error("Ambiguous account")`. For one match, locked status takes precedence over disabled status: reject with `Error("Account is locked")` when locked, otherwise reject with `Error("Account is disabled")` when not enabled. Resolve with `"Recovery instructions queued"` otherwise.

Do not mutate `users`. Malformed email fields on unrelated user records are merely nonmatches; booleans are already strongly typed.

