import { requestRecovery, RecoveryUser } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
async function rejects(promise: Promise<unknown>, expected: string, message: string): Promise<void> {
  try { await promise; } catch (error) {
    assert(error instanceof Error, `${message}: wrong rejection type`);
    assert(error.message === expected, `${message}: expected ${expected}, got ${error.message}`);
    return;
  }
  throw new Error(`${message}: did not reject`);
}

async function main(): Promise<void> {
  const users: RecoveryUser[] = [
    { email: " User@Example.COM ", enabled: true, locked: false },
    { email: "malformed-address", enabled: true, locked: false },
  ];
  const snapshot = JSON.stringify(users);
  assert(await requestRecovery(" user@example.com ", users) === "Recovery instructions queued", "successful recovery");
  assert(JSON.stringify(users) === snapshot, "users were mutated");

  await rejects(requestRecovery("   ", users), "Email is required", "required email");
  await rejects(requestRecovery("not-an-email", users), "Invalid email", "invalid email");
  await rejects(requestRecovery("none@example.com", users), "Account not found", "missing account");
  await rejects(requestRecovery("dup@example.com", [
    { email: "Dup@Example.com", enabled: true, locked: false },
    { email: " dup@example.com ", enabled: false, locked: true },
  ]), "Ambiguous account", "normalized duplicate account");
  await rejects(requestRecovery("locked@example.com", [
    { email: "locked@example.com", enabled: false, locked: true },
  ]), "Account is locked", "locked takes precedence");
  await rejects(requestRecovery("disabled@example.com", [
    { email: "disabled@example.com", enabled: false, locked: false },
  ]), "Account is disabled", "disabled account");
  await rejects(requestRecovery("valid@example.com", [
    { email: "not valid@", enabled: true, locked: false },
  ]), "Account not found", "malformed unrelated user is a nonmatch");
}

main().catch(error => { throw error; });

